/**
 * @distilled.cloud/kalshi -- Kalshi Trade API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model that
 * `scripts/convert.ts` converts from Kalshi's OpenAPI spec
 * (https://docs.kalshi.com/openapi.yaml). Everything else in this folder is
 * hand-written.
 *
 * @example
 * ```ts
 * import * as Kalshi from "@distilled.cloud/kalshi";
 *
 * const markets = yield* Kalshi.getMarkets({ status: "open", limit: 10 });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  KalshiProtocol,
  authHeaders,
  preSignText,
  signText,
  type KalshiOpError,
  type KalshiOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts -- the ops raise the service-local
// classes.
export * from "./services/kalshi.ts";
export { BadRequest, Conflict, Forbidden, NotFound } from "./services/kalshi.ts";
